head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > M > setHoliday]<br/>Calendar 컴포넌트에 휴일로 표시할 날짜를 설정합니다.",
    "validation" : [
        "date(필수) 파라미터로 휴일로 설정할 날짜를 'yyyyMMdd' 8자리 포맷의 문자열로 설정합니다.",
        "date 파라미터는 공백으로 구분하여 여러 날짜를 동시에 설정할 수 있습니다.",
        "'*MMdd' 포맷으로 설정하면 매년 반복되는 휴일로 적용됩니다.",
        "휴일로 설정된 날짜에는 'w2calendar_holiday' CSS 클래스가 적용됩니다.",
        "deleted(선택, 기본값 false) 파라미터로 기존에 설정된 휴일 정보를 삭제할지 true/false 로 설정합니다.",
        "deleted=true 설정 시 기존에 setHoliday() 메소드로 설정한 휴일 정보를 모두 삭제한 후 date 파라미터 날짜를 추가합니다.",
        "deleted=false (기본값) 설정 시 기존에 setHoliday() 메소드로 설정한 휴일 정보를 유지한 후 date 파라미터 날짜를 추가합니다.",
        "renderType=component 일때 휴일에 설정되는 'w2calendar_holiday' CSS 클래스가 표시됩니다.",
        "setHolidayRef() 메소드로 휴일 정보가 설정되면 setHoliday() 메소드로 설정된 휴일 정보는 무시됩니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // renderType=component 고정 (w2calendar_holiday CSS 클래스 표시 조건)
    let properties = {
        renderType : "component"
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList([]);

    // comp 생성 함수 호출 (createBasicCalendar 내부에서 gotoCalendar('20251111') 호출 → 초기 표시월: 2025-11)
    await $c.gcm.createBasicCalendar(cList, eList);
}



// setHoliday 호출 (선택된 케이스에 따라 분기)
// validation:
//  - date(필수): 'yyyyMMdd' 8자리 포맷 String, 공백 구분 시 여러 날짜 동시 설정, '*MMdd' 매년 반복
//  - deleted(선택, 기본값 false): true 시 기존 휴일 삭제 후 추가, false 시 유지 후 추가
//  - renderType=component 일때 'w2calendar_holiday' CSS 클래스 적용
//  - setHolidayRef() 가 설정되면 setHoliday() 정보는 무시됨
//  - removeHoliday() 호출 시 setHoliday()로 설정한 휴일 모두 제거
scwin.btn_setHoliday_onclick = function (e) {
    let caseId = con_gotoCase.getValue();
    let callLog = "";

    if (caseId === '1') {
        // 케이스 1: 단일 날짜 - 'yyyyMMdd' 8자리 포맷
        target1.setHoliday("20251115");
        callLog = "setHoliday('20251115')";
    } else if (caseId === '2') {
        // 케이스 2: 공백으로 구분하여 여러 날짜 동시 설정
        target1.setHoliday("20251115 20251120");
        callLog = "setHoliday('20251115 20251120')";
    } else if (caseId === '3') {
        // 케이스 3: '*MMdd' 매년 반복 휴일 (현재 표시월 2025-11, '*1105' → 2025-11-05 적용)
        target1.setHoliday("*1105");
        callLog = "setHoliday('*1105')";
    } else if (caseId === '4') {
        // 케이스 4: deleted=false (기본값) - 기존 휴일 유지 후 추가
        target1.setHoliday("20251115");
        target1.setHoliday("20251120");
        callLog = "setHoliday('20251115') + setHoliday('20251120') (deleted 생략 → 기본값 false)";
    } else if (caseId === '5') {
        // 케이스 5: deleted=true - 기존 휴일 삭제 후 추가
        target1.setHoliday("20251115");
        target1.setHoliday("20251125", true);
        callLog = "setHoliday('20251115') + setHoliday('20251125', true)";
    } else if (caseId === '6') {
        // 케이스 6: setHolidayRef 가 우선, setHoliday 무시
        target1.setHolidayRef("data:dlt_holidayref.label");
        target1.setHoliday("20251120");
        callLog = "setHolidayRef('data:dlt_holidayref.label') + setHoliday('20251120')";
    }

    // 호출 후 휴일 셀 일자 + 첫 번째 휴일 셀의 className (w2calendar_holiday 클래스 적용 여부)
    let holidayCells = target1.render.querySelectorAll('.w2calendar_holiday');
    let holidayDays = [];
    for (var i = 0; i < holidayCells.length; i++) {
        holidayDays.push(holidayCells[i].textContent);
    }
    let firstClassName = holidayCells.length > 0 ? holidayCells[0].className : '(휴일 셀 없음)';

    wf_body_bottom.getObj("scwin").setReturnValue("[호출] " + callLog);
    wf_body_bottom.getObj("scwin").setReturnValue("[호출 후 휴일 일자] " + holidayDays.join(','));
    wf_body_bottom.getObj("scwin").setReturnValue("[첫 휴일 셀 className] " + firstClassName);
};
